const PREM_TAX = 0.065
const FREE_TAX = 0.105

class Localized_Item_Names {
	constructor(localized_map){
		this.localized_map = localized_map
	}

	get(item_name){
		if (this.localized_map.has(item_name)) {
			return this.localized_map.get(item_name).get($('#language').val())
		}
		else if (item_name.includes("@")) {
			if (this.localized_map.has(item_name.substring(0, item_name.length-2))) {
				return this.localized_map.get(item_name.substring(0, item_name.length-2)).get($('#language').val())
			}
		}
		return item_name
	}
}

